-- Original starter schema, to verify upgrades preserve existing data.
CREATE TABLE "Participants" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "StravaAthleteId" bigint NOT NULL,
  "DisplayName" text NOT NULL,
  "AccessToken" text,
  "RefreshToken" text,
  "TokenExpiresAt" timestamp with time zone
);
CREATE UNIQUE INDEX "IX_Participants_StravaAthleteId" ON "Participants" ("StravaAthleteId");
CREATE TABLE "Challenges" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Name" text NOT NULL,
  "StartsOn" date NOT NULL,
  "EndsOn" date NOT NULL,
  "Cutoff" time without time zone NOT NULL,
  "MinimumMinutes" integer NOT NULL
);
CREATE TABLE "Activities" (
  "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "StravaActivityId" bigint NOT NULL,
  "ParticipantId" integer NOT NULL REFERENCES "Participants" ("Id") ON DELETE CASCADE,
  "StartUtc" timestamp with time zone NOT NULL,
  "StartLocal" timestamp with time zone NOT NULL,
  "ElapsedSeconds" integer NOT NULL,
  "MovingSeconds" integer NOT NULL,
  "SportType" text NOT NULL
);
CREATE UNIQUE INDEX "IX_Activities_StravaActivityId" ON "Activities" ("StravaActivityId");
CREATE INDEX "IX_Activities_ParticipantId_StartLocal" ON "Activities" ("ParticipantId", "StartLocal");
